        var fabricDefault = new HashMap<String, Integer>();
        var slots = new HashMap<String, float[][]>();
        var seats = new HashMap<String, float[][]>();
        var slotBones = new HashMap<String, String[][]>();
        boxes0(boxes);
        boxes1(boxes);
        boxes2(boxes);
        boxes3(boxes);
        boxes4(boxes);
        boxes5(boxes);
        boxes6(boxes);
        boxes7(boxes);
        boxes8(boxes);
        boxes9(boxes);
